222: uint32_t impl_psdk_process(psdk_engine* engine,const psdk_frame* frame,psdk_result** result,psdk_status* status){
223:     if(result)*result=nullptr;
224:     const auto identity=frame&&abi(frame->struct_size,frame->abi_version,sizeof(*frame))?perception::FrameInfo{frame->frame_id,frame->timestamp_ns}:perception::FrameInfo{};
225:     try{
226:         if(!engine||!result)invalid("engine and result output are required");
227:         const auto image=validateFrame(frame);std::lock_guard<std::mutex> gate(sdk_lifecycle_mutex);std::lock_guard<std::mutex> lock(engine->mutex);const auto begin=Clock::now();
228:         auto value=std::make_unique<psdk_result>();r28::Status failure;r25::RunOptions options;
229:         options.optimized=true;options.variant=r22::Variant::CompactDirect;
230:         options.run_detection=engine->detection_enabled;options.run_segmentation=engine->segmentation_enabled;
231:         const auto code=engine->pipeline->tryRun(image,identity,options,value->output,failure);if(code)return putStatus(status,failure);
232:         value->width=frame->width;value->height=frame->height;value->frame=identity;value->style=engine->style;
233:         if(engine->segmentation_enabled&&value->output.mask().size()!=std::size_t(frame->width)*frame->height)throw r28::Failure({result_invalid,0,"sdk.result",{},"Segmentation result does not cover the source frame",identity});
234:         value->detections.reserve(value->output.det.size());
235:         for(const auto& det:value->output.det){psdk_detection copy{};copy.class_id=det.class_id;copy.confidence=det.confidence;
236:             copy.x1=det.x1;copy.y1=det.y1;copy.x2=det.x2;copy.y2=det.y2;copyText(copy.class_name,det.class_name.c_str());value->detections.push_back(copy);}
237:         const auto& out=value->output;const auto feature=[&](int i){return out.features[i].end_ms-out.features[i].start_ms;};
238:         value->timings={out.pack_ms,feature(1),out.det_infer_ms,feature(3),feature(4),out.seg_infer_ms,feature(6),out.graph_ms,elapsed(begin)};
239:         *result=value.release();return putStatus(status,0,0,identity);
240:     }catch(const std::exception& e){return caught(status,e,inference_failed,"sdk.process",identity);}
241:     catch(...){return putStatus(status,inference_failed,0,identity,"sdk.process","","Unknown exception");}
242: }
